<?php
session_start();require_once __DIR__.'/auth.php';ff_guard();if(!isset($_SESSION['admin_id'])){header('Location: login.php');exit;}require_once __DIR__.'/../fastfood/database.php';require_once __DIR__.'/../fastfood/lang.php';
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$status=$_GET['status']??'all';
$where="status IN ('yakunlangan','bekor qilingan') AND DATE(created_at) BETWEEN ? AND ?";$params=[$from,$to];if($status==='yakunlangan'||$status==='bekor qilingan'){$where.=' AND status=?';$params[]=$status;}
$st=$pdo->prepare("SELECT * FROM orders WHERE $where ORDER BY created_at DESC");$st->execute($params);$orders=$st->fetchAll();
$cancelReasons=[];
if($orders){$ids=array_map(fn($o)=>(int)$o['id'],$orders);$ph=implode(',',array_fill(0,count($ids),'?'));$rs=$pdo->prepare("SELECT oc.order_id, oc.reason, oc.created_at FROM order_cancellations oc INNER JOIN (SELECT order_id, MAX(id) max_id FROM order_cancellations WHERE order_id IN ($ph) GROUP BY order_id) x ON x.max_id=oc.id");$rs->execute($ids);foreach($rs->fetchAll() as $r){$cancelReasons[(int)$r['order_id']]=$r;}}
$viewOrder=null;$viewItems=[];
if(isset($_GET['view'])){$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([(int)$_GET['view']]);$viewOrder=$s->fetch();$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([(int)$_GET['view']]);$viewItems=$s->fetchAll();}
$lang=ff_current_lang();$completed=0;$cancelled=0;$revenue=0;foreach($orders as $o){if($o['status']==='yakunlangan'){$completed++;$revenue+=(float)$o['total'];}else$cancelled++;}
?>
<!doctype html><html lang="<?=$lang?>"><head><meta charset="utf-8"><link rel="icon" type="image/svg+xml" href="../img/favicon.svg"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FastFood — Arxiv</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/theme-elegant.css?v=2"><script src="../js/theme.js"></script><script src="../js/admin-i18n.js" defer></script><style>.cancel-reason-box{grid-column:1/-1;background:var(--danger-soft,#fff1f2);border:1px solid var(--danger-border,#fecdd3);border-radius:14px;padding:12px}.cancel-reason-box span{display:block;color:var(--muted,#777);font-size:12px;margin-bottom:5px}.cancel-reason-box b{color:var(--text,#222);line-height:1.5}.cancel-reason-inline{display:inline-block;max-width:240px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;vertical-align:middle;color:var(--text,#222);background:var(--surface-2,#f7f7f7);border-radius:8px;padding:5px 8px;font-size:12px}</style><script src="../js/parallax.js?v=1" defer></script>
</head><body><?php include __DIR__.'/sidebar.php'; ?><main class="admin-content"><div class="page-topline"><div><div class="eyebrow" data-i18n="ARXIV">ARXIV</div><h1 data-i18n="Buyurtmalar arxivi">Buyurtmalar arxivi</h1><p class="admin-muted" data-i18n="Yakunlangan va bekor qilingan buyurtmalarni sana bo‘yicha toping.">Yakunlangan va bekor qilingan buyurtmalarni sana bo‘yicha toping.</p></div><form class="date-filter" method="get"><input type="date" name="from" value="<?=$from?>"><span>→</span><input type="date" name="to" value="<?=$to?>"><select name="status"><option value="all" data-i18n="Barchasi">Barchasi</option><option value="yakunlangan" <?=$status==='yakunlangan'?'selected':''?> data-i18n="Yakunlangan">Yakunlangan</option><option value="bekor qilingan" <?=$status==='bekor qilingan'?'selected':''?> data-i18n="Bekor qilingan">Bekor qilingan</option></select><button class="btn btn-secondary" data-i18n="Filtr">Filtr</button></form></div>
<section class="metric-strip"><div><span data-i18n="Yakunlangan">Yakunlangan</span><strong><?=$completed?></strong></div><div><span data-i18n="Bekor qilingan">Bekor qilingan</span><strong><?=$cancelled?></strong></div><div><span data-i18n="Arxiv tushumi">Arxiv tushumi</span><strong><?=number_format($revenue,0,'',' ')?> <small>so‘m</small></strong></div></section>
<?php if($viewOrder): ?><div class="admin-panel archive-detail"><div class="panel-heading"><div><div class="panel-kicker">ORDER #<?=$viewOrder['id']?></div><h2 data-i18n="Buyurtma tafsiloti">Buyurtma tafsiloti</h2></div><a class="btn btn-secondary" href="archive.php?from=<?=$from?>&to=<?=$to?>&status=<?=$status?>" data-i18n="Yopish">Yopish</a></div><div class="detail-grid"><div><span data-i18n="Mijoz">Mijoz</span><b><?=htmlspecialchars($viewOrder['customer_name'])?></b></div><div><span data-i18n="Telefon">Telefon</span><b><?=htmlspecialchars($viewOrder['phone'])?></b></div><div><span data-i18n="Stol">Stol</span><b><?=htmlspecialchars($viewOrder['table_number']?:'—')?></b></div><div><span data-i18n="Sana">Sana</span><b><?=htmlspecialchars($viewOrder['created_at'])?></b></div><?php if($viewOrder['status']==='bekor qilingan'): ?><div class="cancel-reason-box"><span data-i18n="Bekor qilish sababi">Bekor qilish sababi</span><b><?=htmlspecialchars($cancelReasons[(int)$viewOrder['id']]['reason'] ?? "Sabab ko‘rsatilmagan")?></b></div><?php endif; ?></div><table><thead><tr><th data-i18n="Mahsulot">Mahsulot</th><th data-i18n="Narx">Narx</th><th data-i18n="Soni">Soni</th></tr></thead><tbody><?php foreach($viewItems as $it): ?><tr><td><?=htmlspecialchars($it['product_name'])?></td><td><?=number_format($it['price'],0,'',' ')?> so‘m</td><td><?=$it['quantity']?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<div class="admin-panel table-panel-pro"><div class="panel-heading"><div><div class="panel-kicker" data-i18n="NATIJALAR">NATIJALAR</div><h2 data-i18n="Arxiv buyurtmalari">Arxiv buyurtmalari</h2></div><span class="soft-count"><?=count($orders)?></span></div><div class="table-scroll"><table><thead><tr><th>#</th><th data-i18n="Sana">Sana</th><th data-i18n="Mijoz">Mijoz</th><th data-i18n="Stol">Stol</th><th data-i18n="Holat">Holat</th><th data-i18n="Jami">Jami</th><th data-i18n="Bekor qilish sababi">Bekor qilish sababi</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><b>#<?=$o['id']?></b></td><td><?=htmlspecialchars($o['created_at'])?></td><td><?=htmlspecialchars($o['customer_name'])?></td><td><?=htmlspecialchars($o['table_number']?:'—')?></td><td><span class="status-pill <?=$o['status']==='yakunlangan'?'success':'danger'?>"><?=htmlspecialchars($o['status'])?></span></td><td><strong><?=number_format($o['total'],0,'',' ')?> so‘m</strong></td><td><?php if($o['status']==='bekor qilingan'): ?><span class="cancel-reason-inline"><?=htmlspecialchars($cancelReasons[(int)$o['id']]['reason'] ?? "—")?></span><?php else: ?>—<?php endif; ?></td><td><a class="btn btn-secondary btn-sm" href="archive.php?view=<?=$o['id']?>&from=<?=$from?>&to=<?=$to?>&status=<?=$status?>" data-i18n="Ko‘rish">Ko‘rish</a></td></tr><?php endforeach; if(!$orders): ?><tr><td colspan="8" class="empty-table" data-i18n="Tanlangan davrda arxiv yo‘q.">Tanlangan davrda arxiv yo‘q.</td></tr><?php endif; ?></tbody></table></div></div>
</main><script src="../js/lang-switch.js"></script></body></html>
